	private void seedBaseGroups() {
		for (int expressionId = 1; expressionId <= baseLogicalExpressionCount; expressionId++) {
			int groupId = query.relGroup(expressionId);
			ensureGroupCapacity(groupId);
			groupCount = Math.max(groupCount, groupId);
			linkLogical(groupId, expressionId);
		}
	}

	private int findLogical(int operatorTag, int payloadId, int semanticScopeId, int executionDomainId,
			int[] childGroupIds, int childOffset, int childCount) {
		int baseExpressionId = query.findRelation(operatorTag, payloadId, semanticScopeId, executionDomainId,
				childGroupIds, childOffset, childCount);
		if (baseExpressionId != 0) {
			return baseExpressionId;
		}
		int overlayId = logicalOverlay.findLogical(operatorTag, payloadId, semanticScopeId, executionDomainId,
				childGroupIds, childOffset, childCount);
		return overlayId == 0 ? 0 : baseLogicalExpressionCount + overlayId;
	}

	private void ensureTargetGroup(int logicalExpressionId, int targetGroupId) {
		int existingGroupId = logicalGroupId(logicalExpressionId);
		if (existingGroupId != targetGroupId) {
			throw crossGroupInvariant("logical", logicalExpressionId, existingGroupId, targetGroupId);
		}
	}

	private static PackedMemoInvariantException crossGroupInvariant(String kind, int expressionId,
			int existingGroupId, int targetGroupId) {
		return new PackedMemoInvariantException(kind + " expression " + expressionId + " already belongs to group "
				+ existingGroupId + " and cannot move to group " + targetGroupId);
	}

	private void linkLogical(int groupId, int logicalExpressionId) {
		ensureLogicalExpressionCapacity(logicalExpressionId);
		nextLogicalExpression[logicalExpressionId] = firstLogicalByGroup[groupId];
		firstLogicalByGroup[groupId] = logicalExpressionId;
	}

	private void linkPhysical(int groupId, int physicalExpressionId) {
		ensurePhysicalExpressionCapacity(physicalExpressionId);
		nextPhysicalExpression[physicalExpressionId] = firstPhysicalByGroup[groupId];
		firstPhysicalByGroup[groupId] = physicalExpressionId;
	}

	private void checkChildGroups(int[] childGroupIds, int childOffset, int childCount) {
		if (childGroupIds == null || childOffset < 0 || childCount < 0
				|| childOffset > childGroupIds.length - childCount) {
			throw new IndexOutOfBoundsException("invalid child-group slice");
		}
		for (int ordinal = 0; ordinal < childCount; ordinal++) {
			checkGroupId(childGroupIds[childOffset + ordinal]);
		}
	}

	private void checkGroupId(int groupId) {
		if (groupId <= 0 || groupId > groupCount) {
			throw new IndexOutOfBoundsException("unknown memo group " + groupId);
		}
	}

	private void checkLogicalExpressionId(int logicalExpressionId) {
		if (logicalExpressionId <= 0 || logicalExpressionId > logicalExpressionCount()) {
			throw new IndexOutOfBoundsException("unknown logical expression " + logicalExpressionId);
		}
	}

	private void ensureGroupCapacity(int requiredGroupId) {
		if (requiredGroupId < firstLogicalByGroup.length) {
			return;
		}
		int newCapacity = firstLogicalByGroup.length;
		while (newCapacity <= requiredGroupId) {
			newCapacity <<= 1;
		}
		firstLogicalByGroup = Arrays.copyOf(firstLogicalByGroup, newCapacity);
		firstPhysicalByGroup = Arrays.copyOf(firstPhysicalByGroup, newCapacity);
	}

	private void ensureLogicalExpressionCapacity(int requiredExpressionId) {
		if (requiredExpressionId < nextLogicalExpression.length) {
			return;
		}
		int newCapacity = nextLogicalExpression.length;
		while (newCapacity <= requiredExpressionId) {
			newCapacity <<= 1;
		}
		nextLogicalExpression = Arrays.copyOf(nextLogicalExpression, newCapacity);
	}

	private void ensurePhysicalExpressionCapacity(int requiredExpressionId) {
		if (requiredExpressionId < nextPhysicalExpression.length) {
			return;
		}
		int newCapacity = nextPhysicalExpression.length;
		while (newCapacity <= requiredExpressionId) {
			newCapacity <<= 1;
		}
		nextPhysicalExpression = Arrays.copyOf(nextPhysicalExpression, newCapacity);
		physicalSourceLogicalExpressionIds = Arrays.copyOf(physicalSourceLogicalExpressionIds, newCapacity);
	}

	private void ensureOverlayRuleCapacity(int requiredOverlayId) {
		if (requiredOverlayId < overlayLogicalRuleMasks.length) {
			return;
		}
		int newCapacity = overlayLogicalRuleMasks.length;
		while (newCapacity <= requiredOverlayId) {
			newCapacity <<= 1;
		}
		overlayLogicalRuleMasks = Arrays.copyOf(overlayLogicalRuleMasks, newCapacity);
	}
